CREATE OR REPLACE FUNCTION public.validate_phase2_files() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f jsonb; BEGIN IF TG_OP='UPDATE' AND NEW.attachments=OLD.attachments THEN RETURN NEW; END IF; IF jsonb_typeof(NEW.attachments)<>'array' THEN RAISE EXCEPTION 'Invalid attachments'; END IF; FOR f IN SELECT value FROM jsonb_array_elements(NEW.attachments) LOOP IF f->>'path' NOT LIKE auth.uid()::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='phase2-files' AND name=f->>'path') THEN RAISE EXCEPTION 'Attachment must be your uploaded file'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER validate_leave_files BEFORE INSERT OR UPDATE ON public.leave_requests FOR EACH ROW EXECUTE FUNCTION public.validate_phase2_files(); CREATE TRIGGER validate_registry_files BEFORE INSERT OR UPDATE ON public.correspondence FOR EACH ROW EXECUTE FUNCTION public.validate_phase2_files();
CREATE OR REPLACE FUNCTION public.validate_document_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.category NOT IN ('Policies','SOPs','Administrative Orders','Circulars','Standing Orders','Training Manuals','Personnel Documents','Financial Documents','Procurement Documents','Meeting Minutes','Cadet Files') THEN RAISE EXCEPTION 'Unknown document category'; END IF; IF NEW.status='Pending' AND NEW.stage NOT BETWEEN 1 AND 4 THEN RAISE EXCEPTION 'Invalid document approval stage'; END IF; IF TG_OP='INSERT' AND NOT public.phase2_admin() THEN IF NOT EXISTS(SELECT 1 FROM public.officers WHERE user_id=auth.uid() AND section_id=NEW.section_id) THEN RAISE EXCEPTION 'Choose your assigned section'; END IF; IF NEW.category='Personnel Documents' AND NOT public.has_any_role(auth.uid(),ARRAY['hr_officer']::public.app_role[]) THEN RAISE EXCEPTION 'HR permission required'; END IF; IF NEW.category='Financial Documents' AND NOT public.has_any_role(auth.uid(),ARRAY['finance_officer']::public.app_role[]) THEN RAISE EXCEPTION 'Finance permission required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_document_record BEFORE INSERT OR UPDATE ON public.erp_documents FOR EACH ROW EXECUTE FUNCTION public.validate_document_record();
CREATE OR REPLACE FUNCTION public.validate_document_file() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='phase2-files' AND name=NEW.file_path) THEN RAISE EXCEPTION 'Upload the file before saving'; END IF; IF NEW.file_path NOT LIKE auth.uid()::text||'/%' AND NOT EXISTS(SELECT 1 FROM public.document_versions WHERE document_id=NEW.document_id AND file_path=NEW.file_path) THEN RAISE EXCEPTION 'File ownership mismatch'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_document_file BEFORE INSERT ON public.document_versions FOR EACH ROW EXECUTE FUNCTION public.validate_document_file();
DROP POLICY phase2_storage_read ON storage.objects;
CREATE POLICY phase2_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='phase2-files' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.document_versions v WHERE v.file_path=name AND public.can_read_document(v.document_id)) OR EXISTS(SELECT 1 FROM public.correspondence c CROSS JOIN LATERAL jsonb_array_elements(c.attachments) f WHERE f->>'path'=name) OR EXISTS(SELECT 1 FROM public.leave_requests l CROSS JOIN LATERAL jsonb_array_elements(l.attachments) f WHERE f->>'path'=name)));
REVOKE ALL ON FUNCTION public.act_on_leave(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.act_on_leave(uuid,boolean,text) TO authenticated;
REVOKE UPDATE ON public.notifications FROM authenticated; GRANT UPDATE(read) ON public.notifications TO authenticated;
CREATE OR REPLACE FUNCTION public.audit_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid text;headers jsonb; BEGIN rid:=coalesce(to_jsonb(NEW)->>'id',to_jsonb(OLD)->>'id'); BEGIN headers:=nullif(current_setting('request.headers',true),'')::jsonb; EXCEPTION WHEN OTHERS THEN headers:='{}'; END; INSERT INTO public.audit_logs(user_id,user_email,action,table_name,record_id,details,ip_address) VALUES(auth.uid(),(SELECT email FROM public.profiles WHERE id=auth.uid()),TG_OP,TG_TABLE_NAME,rid,CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END,coalesce(headers->>'x-forwarded-for',headers->>'cf-connecting-ip')); RETURN coalesce(NEW,OLD); END $$;
CREATE OR REPLACE FUNCTION public.phase2_decision_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldj jsonb:=to_jsonb(OLD); newj jsonb:=to_jsonb(NEW); event text;lastentry jsonb; BEGIN IF newj->'history'=oldj->'history' THEN RETURN NEW; END IF; lastentry:=(newj->'history')->-1; event:=upper(lastentry->>'action'); IF event IN ('APPROVED','APPROVE') AND newj->>'status'='Published' THEN event:='PUBLISH'; END IF; IF event IN ('APPROVED','REJECTED','APPROVE','REJECT','PUBLISH','ROLLBACK','ADVANCE','SUBMIT') THEN INSERT INTO public.audit_logs(user_id,user_email,action,table_name,record_id,details,ip_address) VALUES(auth.uid(),(SELECT email FROM public.profiles WHERE id=auth.uid()),event,TG_TABLE_NAME,newj->>'id',lastentry,nullif(current_setting('request.headers',true),'')::jsonb->>'x-forwarded-for'); END IF; RETURN NEW; END $$;
CREATE TRIGGER decision_audit_leave AFTER UPDATE ON public.leave_requests FOR EACH ROW EXECUTE FUNCTION public.phase2_decision_audit(); CREATE TRIGGER decision_audit_registry AFTER UPDATE ON public.correspondence FOR EACH ROW EXECUTE FUNCTION public.phase2_decision_audit(); CREATE TRIGGER decision_audit_documents AFTER UPDATE ON public.erp_documents FOR EACH ROW EXECUTE FUNCTION public.phase2_decision_audit();